mapper.select:
select
a.id, a.type, a.status, a.remark, a.create_by, a.create_time,
group_concat(su.user_name) as receiver
from t_mail_forewarning a
left join sys_user su on su.user_id regexp(select replace ( a.receiver , ',','|' ))

    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
    and a.type = #{type}
    and a.receiver = #{receiver}
    and a.status = #{status}


${params.dataScope}
group by a.id
